{
  "$schema": "https://json.schemastore.org/tsconfig",
  "compilerOptions": {
    "target": "ESNext",
    "module": "ESNext",
    "lib": [
      "DOM",
      "ESNext"
    ],
    "moduleResolution": "bundler",
    "jsx": "react-jsx",
    "strict": true,
    "esModuleInterop": true,
    "isolatedModules": true,
    "resolveJsonModule": true,
    "skipLibCheck": true,
    "allowJs": false,
    "incremental": false,
    "noEmit": true,
    "types": [
      "react",
      "react-dom",
      "vitest/importMeta"
    ],
    "baseUrl": ".",
    "paths": {
      "@semio/ui": [
        "./index.tsx"
      ],
      "@semio/ui/*": [
        "./*"
      ],
      "@elements/ui": [
        "../../elements/ui/index.tsx"
      ],
      "@elements/ui/elements": [
        "../../elements/ui/index.tsx"
      ],
      "@elements/ui/*": [
        "../../elements/ui/*"
      ],
      "@semio/js": [
        "../js"
      ],
      "@semio/js/*": [
        "../js/*"
      ],
      "@semio/assets": [
        "../assets"
      ],
      "@semio/assets/*": [
        "../assets/*"
      ]
    }
  },
  "exclude": [
    "node_modules",
    "storybook-static"
  ]
}

