      segments.push(\`Expires=\${options.expires.toUTCString()}\`);
    }
    if (options.httpOnly) {
      segments.push("HttpOnly");
    }
    if (options.secure) {
      segments.push("Secure");
    }
    if (options.partitioned) {
      segments.push("Partitioned");
    }
